-- Estimativa Embrapa Agritec (soja, plantio 15/11) por municipio e safra.
-- fator_clima = produtividade almejada final / expectativa (3 t/ha); 1 = sem perda.
DROP TABLE IF EXISTS clima_agritec CASCADE;
CREATE TABLE clima_agritec (
  municipio_id int, safra int, data_plantio date, dias int,
  prod_almejada numeric, prod_media_municipio numeric, fator_clima numeric,
  isna_medio numeric, dias_isna_baixo int, deficiencia_total numeric,
  chuva_total_mm numeric, dias_tmax_35 int,
  PRIMARY KEY (municipio_id, safra));

-- conferencia: fator medio por safra
SELECT safra, COUNT(*) AS municipios, ROUND(AVG(fator_clima),3) AS fator_medio,
       ROUND(AVG(isna_medio),3) AS isna_medio
FROM clima_agritec GROUP BY safra ORDER BY safra;
